<?php
namespace App\Domain\Documents\Services;
use App\Domain\Authorization\Enums\GeographicScopeLevel;use App\Models\Document;use App\Models\User;use Illuminate\Database\Eloquent\Builder;
class AuthorizedDocumentQuery{public function for(User $user):Builder{$q=Document::query();if($user->hasRole('Super Administrator'))return $q; $scopes=$user->geographicScopes()->get()->filter->isActive();if($scopes->isEmpty())return $q->whereRaw('1=0');return $q->where(function(Builder $outer)use($scopes){foreach($scopes as $s){$outer->orWhere(function(Builder $x)use($s){match($s->scope_level){GeographicScopeLevel::State=>$x->where('state_id',$s->state_id),GeographicScopeLevel::District=>$x->where('district_id',$s->district_id),GeographicScopeLevel::Subdivision=>$x->where('subdivision_id',$s->subdivision_id),GeographicScopeLevel::RevenueCircle=>$x->where('revenue_circle_id',$s->revenue_circle_id),GeographicScopeLevel::Mouza=>$x->where('mouza_id',$s->mouza_id),GeographicScopeLevel::Village=>$x->where('village_id',$s->village_id)};});}});}}
